// Gravitational and repulsive force model
var num = 1000;
var vx = new Array(num);
var vy = new Array(num);
var x = new Array(num);
var y = new Array(num);
var ax = new Array(num);
var ay = new Array(num);

var magnetism = 10.0; // Strength of gravitational force. Negative value becomes repulsive force.
var radius = 1 ; // Radius of circle to draw
var slowFactor = 0.95; // Slows down particle movement

function setup(){
  createCanvas(windowWidth,windowHeight);
  noStroke(); 
  fill(0);
  ellipseMode(RADIUS);
  background(0);
  blendMode(ADD);

  for(var i =0; i< num; i++){
    x[i] = random(width);
    y[i] = random(height);
    vx[i] = 0;
    vy[i] = 0;
    ax[i] = 0;
    ay[i] = 0;
  }
}


function draw(){
  fill(0,0,0);
  rect(0,0,width,height);

  for(var i=0; i<num; i++){
    var distance = dist(touchX, touchY, x[i], y[i]); // dist(x1,y1,x2,y2) Function to calculate distance between two points
    // Acceleration is inversely proportional to the square of the distance from the center of gravity.
    if(distance > 3){ // Do not update acceleration if too close to the mouse.
      ax[i] = magnetism * (touchX - x[i]) / (distance * distance); 
      ay[i] = magnetism * (touchY - y[i]) / (distance * distance);
    }
    vx[i] += ax[i]; // Increase velocity vx by ax per frame.
    vy[i] += ay[i]; // Increase velocity vy by ay per frame.

    vx[i] = vx[i]*slowFactor;
    vy[i] = vy[i]*slowFactor;

    x[i] += vx[i];  // Move vx pixels per frame.
    y[i] += vy[i];  // Move vy pixels per frame.

    var velocities = dist(0,0,vx[i],vy[i]); // Calculate velocity from X and Y components of velocity
    var r = map(velocities, 0, 5, 0, 255); // Calculate color according to velocity
    var g = map(velocities, 0,5, 64, 255);
    var b = map(velocities, 0,5, 128, 255);
    fill(r, g, b, 32);
    ellipse(x[i],y[i],radius,radius);
  }
}

